html:
{#- The Arabic customer quote (SP-62). It never prints a cost, a profit or a margin. -#}
{% extends "smart_power/templates/print/base_rtl.html" %}
{%- set q = quote_print(doc) -%}
{% block title %}
<table class="sp-quote-head">
	<tr>
		<td>
			<h2>{{ _("Quotation") }}</h2>
			<div>{{ _("No.") }}: <span class="sp-num">{{ q.header.quote_no }}</span> · {{ _("Option") }} {{ q.header.option }} · {{ _("Version") }} {{ q.header.version or 1 }}</div>
		</td>
		<td class="sp-quote-meta">
			<div>{{ _("Date") }}: {{ q.header.date }}</div>
			<div>{{ _("Valid Till") }}: {{ q.header.valid_till }}</div>
		</td>
	</tr>
	<tr>
		<td>{{ _("Customer") }}: <strong>{{ q.header.customer or "" }}</strong></td>
		<td class="sp-quote-meta">
			{%- if q.header.system_type %}<div>{{ _("System Type") }}: {{ q.header.system_type }}</div>{% endif %}
			{%- if q.header.site %}<div>{{ _("Site") }}: {{ q.header.site }}</div>{% endif %}
			{%- if doc.sp_execution_period %}<div>{{ _("Execution Period") }}: {{ doc.sp_execution_period }}</div>{% endif %}
		</td>
	</tr>
</table>
{% endblock %}
{% block body %}
{{ sp_block("Quotation", "preamble", doc) }}

<table class="sp-table sp-quote-lines">
	<thead>
		<tr>
			<th>#</th><th>{{ _("Description") }}</th><th>{{ _("Unit") }}</th><th>{{ _("Qty") }}</th>
			<th>{{ _("Unit Price") }}</th><th>{{ _("Total") }}</th>
		</tr>
	</thead>
	<tbody>
	{%- for line in q.lines %}
		<tr>
			<td class="sp-num">{{ line.no }}</td>
			<td>{{ line.description or "" }}</td>
			<td>{{ _(line.uom) if line.uom else "" }}</td>
			<td class="sp-num">{{ frappe.format(line.qty, {"fieldtype": "Float"}) }}</td>
			<td class="sp-amount">{{ money(line.rate, q.totals.currency) }}</td>
			<td class="sp-amount">{{ money(line.amount, q.totals.currency) }}</td>
		</tr>
	{%- endfor %}
	</tbody>
</table>

<table class="sp-quote-totals">
	<tr><td>{{ _("Subtotal") }}</td><td class="sp-amount">{{ money(q.totals.subtotal, q.totals.currency) }}</td></tr>
	{%- if q.totals.discounts %}
	{%- for d in q.totals.discounts %}
	<tr class="sp-quote-discount"><td>{{ d.label }}</td><td class="sp-amount">- {{ money(d.amount, q.totals.currency) }}</td></tr>
	{%- endfor %}
	{%- elif q.totals.discount %}
	<tr><td>{{ _("Discount") }}</td><td class="sp-amount">- {{ money(q.totals.discount, q.totals.currency) }}</td></tr>
	{%- endif %}
	{%- if q.totals.taxes %}
	<tr><td>{{ _("Taxes") }}</td><td class="sp-amount">{{ money(q.totals.taxes, q.totals.currency) }}</td></tr>
	{%- endif %}
	<tr class="sp-quote-grand"><td>{{ _("Total") }}</td><td class="sp-amount">{{ money(q.totals.total, q.totals.currency) }}</td></tr>
</table>
<p class="sp-words">{{ _("Only") }} {{ q.totals.words }} {{ _("no more") }}</p>

{% include "smart_power/templates/print/quote_optional_lines.html" %}

{%- if q.options %}
<div class="sp-quote-options">
	<h3>{{ _("Options") }}</h3>
	<table class="sp-options-side">
		<tr>
		{%- for option in q.options %}
			<td class="{{ 'sp-option-this' if option.is_this else '' }}">
				<h4>{{ _("Option") }} {{ option.label }} <span class="sp-num">({{ option.name }})</span></h4>
				<table class="sp-table">
					{%- for line in option.lines %}
					<tr><td>{{ line.description or "" }}</td><td class="sp-num">{{ frappe.format(line.qty, {"fieldtype": "Float"}) }}</td></tr>
					{%- endfor %}
				</table>
				<div class="sp-option-total">{{ _("Total") }}: <span class="sp-amount">{{ money(option.total, option.currency) }}</span></div>
			</td>
		{%- endfor %}
		</tr>
	</table>
</div>
{%- endif %}

{%- if q.schedule %}
<div class="sp-quote-schedule">
	<h3>{{ _("Payment Schedule") }}</h3>
	<table class="sp-table">
		<thead><tr><th>{{ _("Due Date") }}</th><th>{{ _("Description") }}</th><th>%</th><th>{{ _("Amount") }}</th></tr></thead>
		<tbody>
		{%- for row in q.schedule %}
			<tr><td>{{ row.due_date }}</td><td>{{ row.description }}</td><td class="sp-num">{{ frappe.format(row.portion, {"fieldtype": "Percent"}) }}</td><td class="sp-amount">{{ money(row.amount, q.totals.currency) }}</td></tr>
		{%- endfor %}
		</tbody>
	</table>
</div>
{%- endif %}

{%- if q.plans %}
<div class="sp-quote-plans">
	<h3>{{ _("Installment Plans") }}</h3>
	<table class="sp-table">
		<thead><tr><th>{{ _("Plan") }}</th><th>{{ _("Installment Price") }}</th><th>{{ _("Down Payment") }}</th><th>{{ _("Installments") }}</th><th>{{ _("Cheque Value") }}</th><th>{{ _("From") }}</th><th>{{ _("To") }}</th></tr></thead>
		<tbody>
		{%- for p in q.plans %}
			<tr class="{{ 'sp-plan-chosen' if p.chosen else '' }}"><td>{{ p.name }}</td><td class="sp-amount">{{ money(p.total, q.totals.currency) }}</td><td class="sp-amount">{{ money(p.down, q.totals.currency) }}</td><td class="sp-num">{{ p.installments }} × {{ money(p.installment, q.totals.currency) }}</td><td class="sp-amount">{{ money(p.cheque, q.totals.currency) }}</td><td>{{ p.first_due }}</td><td>{{ p.last_due }}</td></tr>
		{%- endfor %}
		</tbody>
	</table>
</div>
{%- endif %}

{%- for block in sp_blocks("Quotation", doc, ["preamble"]) %}{{ block }}{% endfor %}

{%- if q.loads or q.pumps %}
<div class="sp-quote-annex">
	<h3>{{ _("Technical Annex") }}</h3>
	{%- if q.loads %}
	<table class="sp-table">
		<thead><tr><th>{{ _("Device") }}</th><th>{{ _("Qty") }}</th><th>{{ _("Watts") }}</th><th>{{ _("Day Hours") }}</th><th>{{ _("Night Hours") }}</th></tr></thead>
		<tbody>
		{%- for row in q.loads %}
			<tr><td>{{ row.device }}</td><td class="sp-num">{{ frappe.format(row.qty, {"fieldtype": "Float"}) }}</td><td class="sp-num">{{ frappe.format(row.watts, {"fieldtype": "Float"}) }}</td><td class="sp-num">{{ frappe.format(row.day_hours, {"fieldtype": "Float"}) }}</td><td class="sp-num">{{ frappe.format(row.night_hours, {"fieldtype": "Float"}) }}</td></tr>
		{%- endfor %}
		</tbody>
	</table>
	{%- endif %}
	{%- if q.pumps %}
	<table class="sp-table">
		<thead><tr><th>{{ _("Pump") }}</th><th>{{ _("Power (HP)") }}</th><th>{{ _("Head (m)") }}</th><th>{{ _("Flow (m³/h)") }}</th></tr></thead>
		<tbody>
		{%- for row in q.pumps %}
			<tr><td>{{ row.description }}</td><td class="sp-num">{{ frappe.format(row.hp, {"fieldtype": "Float"}) }}</td><td class="sp-num">{{ frappe.format(row.head_m or 0, {"fieldtype": "Float"}) }}</td><td class="sp-num">{{ frappe.format(row.flow_m3h or 0, {"fieldtype": "Float"}) }}</td></tr>
		{%- endfor %}
		</tbody>
	</table>
	{%- endif %}
</div>
{%- endif %}
{% endblock %}
{% block signatures %}
{{ signature_block(_("The customer"), _("For Smart Power")) }}
{%- if q.stamp %}<div class="sp-stamp"><img src="{{ q.stamp }}" alt=""></div>{% endif %}
{% endblock %}
